PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?minBirth WHERE {
  VALUES ?film { dbr:Swamp_Women dbr:Tracy_Rides }
  {
    SELECT ?film (MIN(?bdate) AS ?minBirth) WHERE {
      VALUES ?film { dbr:Swamp_Women dbr:Tracy_Rides }
      ?film dbo:director ?d .
      ?d dbo:birthDate ?bdate .
    } GROUP BY ?film
  }
  ?film dbo:director ?director .
  ?director dbo:birthDate ?bdate2 .
  FILTER(?bdate2 = ?minBirth)
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER (lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER (lang(?directorLabel) = "en") }
} ORDER BY ?minBirth LIMIT 1

